// SIRAJ Source Finder ("assistant"): NO text is generated by an AI model.
// It understands what you typed (a reference like 2:255, a Surah name, a page of SIRAJ,
// or a keyword) and returns REAL results from the Quran / Hadith / Dua sources with links.
// Because nothing is generated, nothing can be invented.

const NAVIGATION = [
  { words: ["prayer time", "prayer times", "salah time", "namaz", "azan", "adhan"], label: "Prayer times", to: "/prayer" },
  { words: ["qibla", "kaaba direction", "direction of kaaba"], label: "Qibla compass", to: "/qibla" },
  { words: ["tasbeeh", "tasbih", "dhikr counter", "counter"], label: "Digital Tasbeeh", to: "/tasbeeh" },
  { words: ["calendar", "hijri", "islamic date"], label: "Islamic calendar", to: "/calendar" },
  { words: ["ramadan", "sehri", "suhoor", "iftar", "fasting", "roza"], label: "Ramadan", to: "/ramadan" },
  { words: ["recite", "recitation", "tajweed practice", "tilawat"], label: "Recitation practice", to: "/recitation" },
  { words: ["bookmark", "saved"], label: "My bookmarks", to: "/bookmarks" },
  { words: ["progress", "khatm", "streak"], label: "Quran progress", to: "/progress" },
  { words: ["goal", "goals"], label: "My goals", to: "/goals" },
  { words: ["profile", "settings", "password", "language"], label: "Profile & settings", to: "/profile" },
  { words: ["topic", "topics"], label: "Quran topics", to: "/topics" },
];

// A few very well known verses people search by name
const ALIASES = {
  ayatalkursi: { surahNumber: 2, ayahNumber: 255 },
  ayatulkursi: { surahNumber: 2, ayahNumber: 255 },
  ayahtulkursi: { surahNumber: 2, ayahNumber: 255 },
  ayatkursi: { surahNumber: 2, ayahNumber: 255 },
};

const lettersOnly = (s) => String(s || "").toLowerCase().replace(/[^a-z]/g, "");

/**
 * Pure function (easy to test): decides what the user meant.
 * surahs: [{ number, englishName, ... }]
 */
function interpret(rawQuery, surahs = []) {
  const q = String(rawQuery || "").trim().replace(/\s+/g, " ");
  const lower = q.toLowerCase();
  const out = { query: q, reference: null, surah: null, navigation: [], searchTerm: q };

  // "2:255", "2 : 255", "2.255"
  const ref = lower.match(/^(?:surah\s*)?(\d{1,3})\s*[:.]\s*(\d{1,3})$/);
  if (ref && Number(ref[1]) >= 1 && Number(ref[1]) <= 114 && Number(ref[2]) >= 1) {
    out.reference = { surahNumber: Number(ref[1]), ayahNumber: Number(ref[2]) };
    return out;
  }

  const alias = ALIASES[lettersOnly(lower)];
  if (alias) { out.reference = { ...alias }; return out; }

  // "surah 36" / "sura 36"
  const num = lower.match(/^(?:surah|sura|surat)\s*(\d{1,3})$/);
  if (num && Number(num[1]) >= 1 && Number(num[1]) <= 114) {
    out.surah = surahs.find((s) => s.number === Number(num[1])) || { number: Number(num[1]) };
    return out;
  }

  // "surah baqarah", "al-baqarah", "baqarah"
  const nameQuery = lettersOnly(lower.replace(/^(surah|sura|surat)\s+/, ""));
  if (nameQuery.length >= 4) {
    const hit = surahs.find((s) => {
      const n = lettersOnly(s.englishName);
      return n === nameQuery || n.endsWith(nameQuery);
    });
    if (hit) { out.surah = hit; return out; }
  }

  // Pages of SIRAJ mentioned in the sentence (the keyword search still runs)
  NAVIGATION.forEach((nav) => {
    if (nav.words.some((w) => new RegExp(`\\b${w}\\b`).test(lower))) out.navigation.push({ label: nav.label, to: nav.to });
  });
  return out;
}

module.exports = { interpret, NAVIGATION };
